jsonTools.init:
function init(eli) {
  var HEADER_TEXT = "[[CP Entity]] | [[Third Party Name]]";
  var FOOTER_LEFT = "CP Ref: [[Agreement Request Number]]";

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }

  // Build the footer OOXML as a flat OPC package — the canonical format
  // Office.js's insertOoxml accepts. Two cells: left (free text), right
  // (page X of Y via PAGE + NUMPAGES fields). Borders explicitly NONE
  // on every edge so the cells are invisible. <w:tblLayout w:type="fixed"/>
  // locks column widths so the right cell stays right even when content
  // grows on the left. Bold opt-in wraps every run with <w:rPr><w:b/></w:rPr>.
  function _buildFooterOoxml(bold) {
    var rPr = bold ? "<w:rPr><w:b/></w:rPr>" : "";
    var leftText = _xmlEscape(FOOTER_LEFT);
    return [
      '<?xml version="1.0" encoding="utf-8" standalone="yes"?>',
      '<pkg:package xmlns:pkg="http://schemas.microsoft.com/office/2006/xmlPackage">',
        '<pkg:part pkg:name="/_rels/.rels" pkg:contentType="application/vnd.openxmlformats-package.relationships+xml">',
          '<pkg:xmlData>',
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">',
              '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>',
            '</Relationships>',
          '</pkg:xmlData>',
        '</pkg:part>',
        '<pkg:part pkg:name="/word/document.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">',
          '<pkg:xmlData>',
            '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">',
              '<w:body>',
                '<w:tbl>',
                  '<w:tblPr>',
                    '<w:tblW w:w="5000" w:type="pct"/>',
                    '<w:tblBorders>',
                      '<w:top w:val="none" w:sz="0" w:space="0" w:color="auto"/>',
                      '<w:left w:val="none" w:sz="0" w:space="0" w:color="auto"/>',
                      '<w:bottom w:val="none" w:sz="0" w:space="0" w:color="auto"/>',
                      '<w:right w:val="none" w:sz="0" w:space="0" w:color="auto"/>',
                      '<w:insideH w:val="none" w:sz="0" w:space="0" w:color="auto"/>',
                      '<w:insideV w:val="none" w:sz="0" w:space="0" w:color="auto"/>',
                    '</w:tblBorders>',
                    '<w:tblLayout w:type="fixed"/>',
                    '<w:tblCellMar>',
                      '<w:top w:w="0" w:type="dxa"/>',
                      '<w:left w:w="0" w:type="dxa"/>',
                      '<w:bottom w:w="0" w:type="dxa"/>',
                      '<w:right w:w="0" w:type="dxa"/>',
                    '</w:tblCellMar>',
                  '</w:tblPr>',
                  '<w:tblGrid>',
                    '<w:gridCol w:w="5000"/>',
                    '<w:gridCol w:w="5000"/>',
                  '</w:tblGrid>',
                  '<w:tr>',
                    '<w:tc>',
                      '<w:tcPr><w:tcW w:w="5000" w:type="pct"/></w:tcPr>',
                      '<w:p>',
                        '<w:pPr><w:jc w:val="left"/></w:pPr>',
                        '<w:r>', rPr, '<w:t xml:space="preserve">' + leftText + '</w:t></w:r>',
                      '</w:p>',
                    '</w:tc>',
                    '<w:tc>',
                      '<w:tcPr><w:tcW w:w="5000" w:type="pct"/></w:tcPr>',
                      '<w:p>',
                        '<w:pPr><w:jc w:val="right"/></w:pPr>',
                        '<w:r>', rPr, '<w:t xml:space="preserve">Page </w:t></w:r>',
                        '<w:r>', rPr, '<w:fldChar w:fldCharType="begin"/></w:r>',
                        '<w:r>', rPr, '<w:instrText xml:space="preserve">PAGE</w:instrText></w:r>',
                        '<w:r>', rPr, '<w:fldChar w:fldCharType="end"/></w:r>',
                        '<w:r>', rPr, '<w:t xml:space="preserve"> of </w:t></w:r>',
                        '<w:r>', rPr, '<w:fldChar w:fldCharType="begin"/></w:r>',
                        '<w:r>', rPr, '<w:instrText xml:space="preserve">NUMPAGES</w:instrText></w:r>',
                        '<w:r>', rPr, '<w:fldChar w:fldCharType="end"/></w:r>',
                      '</w:p>',
                    '</w:tc>',
                  '</w:tr>',
                '</w:tbl>',
              '</w:body>',
            '</w:document>',
          '</pkg:xmlData>',
        '</pkg:part>',
      '</pkg:package>',
    ].join("");
  }
  function _xmlEscape(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // Header OOXML — single right-aligned paragraph. Using insertOoxml
  // instead of insertParagraph + alignment property because (a) range
  // API is more reliable across Word builds, (b) OOXML round-trips
  // more predictably than properties set via the JS API.
  function _buildHeaderOoxml(bold) {
    var rPr = bold ? "<w:rPr><w:b/></w:rPr>" : "";
    var text = _xmlEscape(HEADER_TEXT);
    return [
      '<?xml version="1.0" encoding="utf-8" standalone="yes"?>',
      '<pkg:package xmlns:pkg="http://schemas.microsoft.com/office/2006/xmlPackage">',
        '<pkg:part pkg:name="/_rels/.rels" pkg:contentType="application/vnd.openxmlformats-package.relationships+xml">',
          '<pkg:xmlData>',
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">',
              '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>',
            '</Relationships>',
          '</pkg:xmlData>',
        '</pkg:part>',
        '<pkg:part pkg:name="/word/document.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">',
          '<pkg:xmlData>',
            '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">',
              '<w:body>',
                '<w:p>',
                  '<w:pPr><w:jc w:val="right"/></w:pPr>',
                  '<w:r>', rPr, '<w:t xml:space="preserve">' + text + '</w:t></w:r>',
                '</w:p>',
              '</w:body>',
            '</w:document>',
          '</pkg:xmlData>',
        '</pkg:part>',
      '</pkg:package>',
    ].join("");
  }

  // ─── Word ops ──────────────────────────────────────────────────────
  // 2026-05-25 v2 fix: use the EXACT same getFooter / getRange pattern
  // that error_review's footer consistency check uses (engine.js:324):
  //   - PascalCase types: "Primary" / "FirstPage" / "EvenPages"
  //   - Fallback chain: section.getFooter ? section.getFooter(t) : section.footers.getItem(t)
  //   - Writes go through range.insertOoxml() not body.insertOoxml()
  // Older Word builds expose `section.footers` collection but not
  // `getFooter()` method — the fallback covers both.
  function _getHF(section, kind, which) {
    // which: "header" | "footer". kind: "Primary" | "FirstPage" | "EvenPages"
    if (which === "header") {
      return section.getHeader ? section.getHeader(kind) : section.headers.getItem(kind);
    }
    return section.getFooter ? section.getFooter(kind) : section.footers.getItem(kind);
  }

  // Single-paragraph footer OOXML with a right-aligned tab stop.
  // Layout: [LEFT TEXT] <tab → right edge> [Page N of M]
  // Tab stop at 9360 dxa (≈ 6.5" from left margin = right page edge for
  // letter paper with 1" margins). Insert at the footer's body root via
  // footer.getRange().insertOoxml(...) — single paragraph stays as one
  // line.
  // We re-inject fresh chrome at every template load (the whole point of
  // this design), so even if Word's save layer corrupts the tab stop on
  // round-trip, the next load wipes + re-injects the canonical chrome.
  function _buildFooterParagraphOoxml(bold) {
    var rPr = bold ? "<w:rPr><w:b/></w:rPr>" : "";
    var leftText = _xmlEscape(FOOTER_LEFT);
    return [
      '<?xml version="1.0" encoding="utf-8" standalone="yes"?>',
      '<pkg:package xmlns:pkg="http://schemas.microsoft.com/office/2006/xmlPackage">',
        '<pkg:part pkg:name="/word/document.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">',
          '<pkg:xmlData>',
            '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">',
              '<w:body>',
                '<w:p>',
                  '<w:pPr>',
                    '<w:tabs><w:tab w:val="right" w:pos="9360"/></w:tabs>',
                    '<w:jc w:val="left"/>',
                  '</w:pPr>',
                  '<w:r>', rPr, '<w:t xml:space="preserve">' + leftText + '</w:t></w:r>',
                  '<w:r>', rPr, '<w:tab/></w:r>',
                  '<w:r>', rPr, '<w:t xml:space="preserve">Page </w:t></w:r>',
                  '<w:r>', rPr, '<w:fldChar w:fldCharType="begin"/></w:r>',
                  '<w:r>', rPr, '<w:instrText xml:space="preserve">PAGE</w:instrText></w:r>',
                  '<w:r>', rPr, '<w:fldChar w:fldCharType="separate"/></w:r>',
                  '<w:r>', rPr, '<w:t>1</w:t></w:r>',
                  '<w:r>', rPr, '<w:fldChar w:fldCharType="end"/></w:r>',
                  '<w:r>', rPr, '<w:t xml:space="preserve"> of </w:t></w:r>',
                  '<w:r>', rPr, '<w:fldChar w:fldCharType="begin"/></w:r>',
                  '<w:r>', rPr, '<w:instrText xml:space="preserve">NUMPAGES</w:instrText></w:r>',
                  '<w:r>', rPr, '<w:fldChar w:fldCharType="separate"/></w:r>',
                  '<w:r>', rPr, '<w:t>1</w:t></w:r>',
                  '<w:r>', rPr, '<w:fldChar w:fldCharType="end"/></w:r>',
                '</w:p>',
              '</w:body>',
            '</w:document>',
          '</pkg:xmlData>',
        '</pkg:part>',
      '</pkg:package>',
    ].join("");
  }

  function _runApply(opts) {
    opts = opts || {};
    var bold = !!opts.bold;
    var wipeBody = !!opts.wipeBody;
    if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
      _toast("Word host not available", "err"); return;
    }
    _toast("⏳ Applying chrome…", "info");
    var diag = { steps: [] };
    function _step(name, payload) { diag.steps.push({ name: name, payload: payload || null, ts: Date.now() }); }
    var KINDS = ["Primary", "FirstPage", "EvenPages"];
    var footerParaOoxml = _buildFooterParagraphOoxml(bold);
    window.eli.host.runRaw("chrome_tester.apply", function (ctx) {
      _step("start");
      var body = ctx.document.body;
      if (wipeBody) {
        _step("wipe_body");
        body.clear();
        body.insertText("(body wiped — type your test content here, then check that the header/footer survive a save+reopen cycle)", "Replace");
      }
      var sections = ctx.document.sections;
      sections.load("items");
      return ctx.sync().then(function () {
        _step("sections_loaded", { count: sections.items.length });
        // STEP 1: clear every header + footer slot
        sections.items.forEach(function (sec, idx) {
          KINDS.forEach(function (kind) {
            try { _getHF(sec, kind, "header").getRange().insertText("", "Replace"); }
            catch (e) { _step("header_clear_threw", { section: idx, kind: kind, err: e && e.message }); }
            try { _getHF(sec, kind, "footer").getRange().insertText("", "Replace"); }
            catch (e) { _step("footer_clear_threw", { section: idx, kind: kind, err: e && e.message }); }
          });
        });
        return ctx.sync();
      }).then(function () {
        _step("clears_synced");
        // STEP 2: write header text. Use native API — insertText then
        // load paragraphs and set alignment on the inserted one.
        // (Full OOXML approach didn't honor alignment in Office.js's
        // insertOoxml for header/footer context — proven 2026-05-25.)
        var headerParas = [];
        sections.items.forEach(function (sec, idx) {
          try {
            var header = _getHF(sec, "Primary", "header");
            header.getRange().insertText(HEADER_TEXT, "Replace");
            header.paragraphs.load("items");
            headerParas.push({ idx: idx, header: header });
            _step("header_text_inserted", { section: idx });
          } catch (e) {
            _step("header_insert_threw", { section: idx, err: e && e.message });
          }
        });
        return ctx.sync().then(function () {
          // STEP 2b: set alignment + bold on each header's paragraph(s).
          headerParas.forEach(function (h) {
            try {
              h.header.paragraphs.items.forEach(function (p) {
                p.alignment = "Right";
                if (bold) p.font.bold = true;
              });
              _step("header_aligned", { section: h.idx, paras: h.header.paragraphs.items.length });
            } catch (e) {
              _step("header_align_threw", { section: h.idx, err: e && e.message });
            }
          });
          return ctx.sync();
        });
      }).then(function () {
        _step("header_done");
        // STEP 3: single-paragraph footer with tab-stop + PAGE/NUMPAGES
        // fields. Abandoned the insertTable approach because Office.js's
        // paragraph.insertOoxml / body.getRange().insertOoxml both rejected
        // or escaped the PAGE field insertion. Single paragraph at the
        // footer body level (via footer.getRange().insertOoxml) is the
        // most reliable path AND matches the canonical Word footer pattern.
        // Tab-stop corruption on round-trip is mitigated by re-injecting
        // fresh chrome on every template load (that's the whole design).
        sections.items.forEach(function (sec, idx) {
          try {
            var footer = _getHF(sec, "Primary", "footer");
            footer.getRange().insertOoxml(footerParaOoxml, "Replace");
            _step("footer_inserted", { section: idx });
          } catch (e) {
            _step("footer_insert_threw", { section: idx, err: e && e.message });
          }
        });
        return ctx.sync();
      }).then(function () {
        _step("done");
        return diag;
      });
    }).then(function (result) {
      eli.log.event("chrome_tester", "apply_diag", result);
      _toast("✅ Chrome applied (" + result.steps.length + " steps)" + (bold ? " — bold ON" : ""), "ok");
      try { console.log("[chrome_tester] apply diag:", result); } catch (_) {}
    }).catch(function (err) {
      diag.error = err && err.message;
      eli.log.event("chrome_tester", "apply_failed", diag);
      try { console.warn("[chrome_tester] apply FAILED:", diag); } catch (_) {}
      _toast("Apply failed: " + (err && err.message || "unknown") + " — see console for step trace", "err");
    });
  }

  function _runClearChrome() {
    if (!window.eli || !window.eli.host || typeof window.eli.host.runRaw !== "function") {
      _toast("Word host not available", "err"); return;
    }
    _toast("⏳ Clearing chrome…", "info");
    var KINDS = ["Primary", "FirstPage", "EvenPages"];
    window.eli.host.runRaw("chrome_tester.clear", function (ctx) {
      var sections = ctx.document.sections;
      sections.load("items");
      return ctx.sync().then(function () {
        sections.items.forEach(function (sec) {
          KINDS.forEach(function (kind) {
            try { _getHF(sec, kind, "header").getRange().insertText("", "Replace"); } catch (e) {}
            try { _getHF(sec, kind, "footer").getRange().insertText("", "Replace"); } catch (e) {}
          });
        });
        return ctx.sync();
      });
    }).then(function () {
      _toast("✅ Headers + footers cleared (body left alone)", "ok");
    }).catch(function (err) {
      _toast("Clear failed: " + (err && err.message || "unknown"), "err");
    });
  }

  // ─── UI ────────────────────────────────────────────────────────────
  function _render() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) { _toast("Dashboard root missing", "err"); return; }
    mount.innerHTML = "";
    var root = document.createElement("div");
    root.style.cssText = "background:#f1f5f9; min-height:100%; padding:0; font:500 13px/1.45 'Inter','Segoe UI',sans-serif; color:#0f172a;";
    root.innerHTML =
      '<div style="background:linear-gradient(180deg,#fff,#f8fafc); border-bottom:1px solid #e2e8f0; padding:14px 20px; display:flex; align-items:center; gap:12px; position:sticky; top:0; z-index:5;">' +
        '<button data-act="back" title="Back" style="border:1px solid #e2e8f0; background:#fff; border-radius:6px; padding:4px 10px; cursor:pointer; font-size:14px; color:#475569;">←</button>' +
        '<div style="font:700 15px/1 \'Inter\',sans-serif; color:#0f172a;">📐 Chrome Tester (header/footer)</div>' +
      '</div>' +
      '<div style="padding:24px 28px; max-width:720px; margin:0 auto;">' +
        '<div style="background:#fff; border:1px solid #e2e8f0; border-radius:10px; padding:20px 22px; box-shadow:0 1px 3px rgba(15,23,42,0.04);">' +
          '<div style="font:700 14px/1.3 \'Inter\',sans-serif; color:#0f172a; margin-bottom:6px;">Test the standard chrome injection</div>' +
          '<div style="font-size:12.5px; color:#475569; margin-bottom:18px; line-height:1.5;">' +
            'Wipes every header/footer slot across every section, then injects a canonical chrome: ' +
            'header with <code style="background:#f1f5f9;padding:1px 5px;border-radius:3px;">[[CP Entity]] | [[Third Party Name]]</code> right-aligned, ' +
            'and footer with <code style="background:#f1f5f9;padding:1px 5px;border-radius:3px;">CP Ref: [[Agreement Request Number]]</code> on the left, ' +
            '<code style="background:#f1f5f9;padding:1px 5px;border-radius:3px;">Page X of Y</code> on the right. ' +
            'Footer uses a borderless 2-column table (most robust against OOXML round-trip drift).' +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:10px;margin-bottom:18px;padding:12px 14px;background:#f8fafc;border-radius:8px;border:1px solid #e2e8f0;">' +
            '<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;">' +
              '<input type="checkbox" id="ct_bold" style="cursor:pointer;width:16px;height:16px;">' +
              '<span><b>Bold</b> — make all chrome text bold</span>' +
            '</label>' +
            '<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;">' +
              '<input type="checkbox" id="ct_wipe_body" style="cursor:pointer;width:16px;height:16px;">' +
              '<span><b>Also wipe body</b> — replace document body with a placeholder line. ' +
              '<span style="color:#94a3b8;">(Off by default — keeps your test content intact.)</span></span>' +
            '</label>' +
          '</div>' +
          '<div style="display:flex;gap:10px;">' +
            '<button data-act="apply" style="flex:1;border:1px solid #1d4ed8;background:linear-gradient(180deg,#3b82f6,#2563eb);color:#fff;border-radius:6px;padding:10px 18px;cursor:pointer;font:600 13.5px/1 \'Inter\',sans-serif;">📐 Apply chrome</button>' +
            '<button data-act="clear" style="border:1px solid #fecaca;background:#fff;color:#b91c1c;border-radius:6px;padding:10px 18px;cursor:pointer;font:600 13.5px/1 \'Inter\',sans-serif;">🗑 Clear chrome</button>' +
          '</div>' +
        '</div>' +
        '<div style="margin-top:18px;padding:12px 14px;background:#fef3c7;border-left:3px solid #d97706;border-radius:6px;font-size:11.5px;color:#78350f;line-height:1.5;">' +
          '💡 <b>Test loop</b>: Apply → look at header/footer in Word → File → Save As → close → re-open → check header/footer survived. ' +
          'If they look right after the round-trip, this OOXML pattern is safe to bake into build_draft\'s template-load flow.' +
        '</div>' +
      '</div>';
    mount.appendChild(root);
    root.querySelector("[data-act='back']").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    };
    root.querySelector("[data-act='apply']").onclick = function () {
      var bold = root.querySelector("#ct_bold").checked;
      var wipeBody = root.querySelector("#ct_wipe_body").checked;
      _runApply({ bold: bold, wipeBody: wipeBody });
    };
    root.querySelector("[data-act='clear']").onclick = _runClearChrome;
  }

  eli.register({
    tile: { app_chrome_tester: _render },
    chrome_tester: { open: _render, apply: _runApply, clear: _runClearChrome },
  });

  eli.log.event("tool", "chrome_tester_initialized", {});
}
